(932, 58, 12543, 1024, 512, 0, 0, 0, 0, 0, 0, 3500, -3500, 0, 80, 80, 80, 0, 936, -1.100000023841858, 1.0, 7, 7, 'The Aldor', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 16712190, 'An ancient order of draenei priests once run by Velen, the Aldor are currently led by High Priestess Ishanah.  They are servants of the naaru in Shattrath City known as the Sha\'tar.  Rivals of the Scryers.', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 16712190),
