(970, 65, 14335, 0, 0, 0, 0, 0, 0, 0, -2500, 0, 0, 0, 0, 0, 0, 0, 980, 0.0, 0.0, 5, 5, 'Sporeggar', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 16712190, 'The sporelings are a mostly peaceful race of mushroom-men native to Outland. Their home is located in the southern bogs of Zangarmarsh. ', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 16712190),
